-- Clock domain crossing with synchronizer
signal r_sync_stage1 : std_logic;
signal r_sync_stage2 : std_logic;

p_cdc_sync: process(i_dest_clk)
begin
    if rising_edge(i_dest_clk) then
        r_sync_stage1 <= i_src_signal;
        r_sync_stage2 <= r_sync_stage1;
    end if;
end process p_cdc_sync;

o_dest <= r_sync_stage2;  -- Only the fully-synchronized last stage is consumed downstream

[Also compliant - multi-bit bus crossing via handshake, not plain double-flopping]
-- i_src_data (multi-bit) must not change while i_src_valid is asserted, and the
-- destination domain acknowledges receipt before the source domain moves on -
-- this handshake is what makes it safe to sample the wide bus, unlike a bare
-- 2-FF synchronizer which is only safe for single-bit signals.
signal r_req_sync1, r_req_sync2 : std_logic;  -- synchronize the REQUEST strobe only (1 bit)

p_dest_sync: process(i_dest_clk)
begin
    if rising_edge(i_dest_clk) then
        r_req_sync1 <= i_src_req;
        r_req_sync2 <= r_req_sync1;      -- now-synchronized single-bit request pulse
        if r_req_sync2 = '1' then
            r_dest_data <= i_src_data;   -- safe to sample the wide bus: source held it stable
        end if;                          -- until the (synchronized) request was seen asserted
    end if;
end process p_dest_sync;

